          "description": "Use this OpenSIP MCP result tool first for existing or prior fit/graph/yagni/sim errors, warnings, findings, scores, sessions, last-run, or current-finding questions. Gets findings from the most recent stored run of a tool, filterable by `severity` (errors/warnings/all) and capped with `limit`. Replays the persisted session and never re-runs fit/graph/yagni/sim. Do not grep .runtime/logs, read datastore.sqlite directly, or re-run a CLI tool to answer stored-result questions.",
          "score": 1.1633962392807007,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "tool": {
                "type": "string",
                "minLength": 1,
                "maxLength": 64
              },
              "severity": {
                "type": "string",
                "enum": [
                  "errors",
                  "warnings",
                  "all"
                ]
              },
              "limit": {
                "type": "integer",
                "exclusiveMinimum": 0,
                "maximum": 500
              }
            },
            "required": [
              "tool"
            ],
            "additionalProperties": false
          }
        },
        {
          "tool_name": "opensip__list_runs",
          "description": "Use this OpenSIP MCP result tool first for existing or prior fit/graph/yagni/sim results, scores, sessions, errors, warnings, findings, or last-run questions. Lists stored runs as lean pointers — id, tool, timing, score/passed, and replay command. Drill into one with show_run, or jump to current findings with get_latest_findings. Replays persisted sessions and never re-runs fit/graph/yagni/sim. Do not grep .runtime/logs, read datastore.sqlite directly, or re-run a CLI tool to answer stored-result questions.",
          "score": 1.1498026847839355,
          "input_schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
              "tool": {
                "type": "string",
                "minLength": 1,
                "maxLength": 64
              },
              "limit": {
                "type": "integer",
                "exclusiveMinimum": 0,
                "maximum": 500
              },
              "summaryOnly": {
                "type": "boolean"
              }
            },
            "additionalProperties": false
          }
        },
        {
          "tool_name": "opensip__blast_radius",
          "description": "Change-impact score for a symbol: direct (depth-1) callers, transitive callers, and a composite blast score (direct + 0.5×transitive) — the same scoring `opensip graph` uses (body-twin-union identity). Default detail=summary returns score metadata and totalMembership without concrete member rows. Pass detail=nodes for paged members, or detail=groups with groupBy=package|file for package/file counts only.",
