                  "type": "string",
                  "minLength": 1,
                  "maxLength": 256
                }
              },
              "filePath": {
                "type": "string",
                "minLength": 1,
                "maxLength": 1024
              },
              "filePrefix": {
                "type": "string",
                "minLength": 1,
                "maxLength": 1024
              },
              "kinds": {
                "maxItems": 16,
                "type": "array",
                "items": {
                  "type": "string",
                  "enum": [
                    "function-declaration",
                    "function-expression",
                    "arrow",
                    "method",
                    "constructor",
                    "getter",
                    "setter",
