              "sourceScope": {
                "default": "all",
                "type": "string",
                "enum": [
                  "production",
                  "test",
                  "all"
                ]
              },
              "generated": {
                "default": "include",
                "type": "string",
                "enum": [
                  "exclude",
                  "include",
                  "only"
                ]
              },
              "limit": {
                "default": 100,
                "type": "integer",
                "exclusiveMinimum": 0,
