                "pattern": "^[A-Za-z0-9_-]+$"
              },
              "groupBy": {
                "default": "none",
                "type": "string",
                "enum": [
                  "none",
                  "package",
                  "file"
                ]
              }
            },
            "required": [
              "symbolId"
            ],
            "additionalProperties": false
          }
        },
        {
          "tool_name": "opensip__get_symbol",
          "description": "Resolve the function/method declared at a project-relative file + line into a stable symbolId (\"<filePath>:<line>:<column>\") + bodyHash. On ambiguity (nested declarations enclosing the line) returns a candidate list — never a silent pick. Use the returned symbolId with who_calls, callees_of, blast_radius, or trace_path.",
