              "line"
            ],
            "additionalProperties": false
          }
        },
        {
          "tool_name": "opensip__select_tests",
          "description": "Select bounded static test candidates and allowlisted verification commands for explicit files. Candidates are not observed coverage and commands are never executed. Inspect trust, uncoveredFiles, graph/inventory identities, freshness, and four-facet coverage.",
